async function load(){const current=++generation;
$('status').textContent='Loading report…';
$('cards').replaceChildren();const selectedReport=$('entity').value,isHotel=selectedReport===HOTEL,p=new URLSearchParams({entity:isHotel?'PERSONAL':selectedReport,from:$('from').value,to:$('to').value});if(isHotel)p.set('unit',HOTEL);try{const response=await fetch('/api/expenses/compact-report?'+p,{cache:'no-store'}),data=await response.json();if(current!==generation)return;if(!response.ok||!data.success)throw Error(data.error||'Could not load report.');report=data;const selected=data.unit===HOTEL?HOTEL:data.entity,options=data.allowedEntities.map(n=>{const o=text('option',n);o.value=n;return o;});if(data.allowedEntities.includes('PERSONAL')){const hotelOption=text('option','Sewak Park Hotel (0992)');hotelOption.value=HOTEL;options.push(hotelOption);}$('entity').replaceChildren(...options);
$('entity').value=selected;render();history.replaceState(null,'','?'+p);
$('status').textContent=(data.displayName?data.displayName+' · ':'')+data.from+' to '+data.to+(data.from==='2026-08-22'?' · August is a partial month':'');}catch(error){if(current!==generation)return;report=null;
$('personalBudgetPeriod').textContent='';
$('personalReviewSummary').textContent='';
for(const id of ['personalBudgets','personalSpendingEntries','personalMoneyTaken','personalBusinessOwes','personalYouOwe','personalSettlements','personalLoans','personalAccounts','personalTransfers','personalTransferReview','personalLoanReview','personalSourceReview','personalWarnings'])$(id).replaceChildren();
setPersonalMode(false);
$('costReviewNotice').hidden=true;
$('operatingCategorySection').hidden=true;
$('tab-samast').hidden=true;
$('samastMonths').replaceChildren();
$('samastBasis').textContent='';if($('tab-samast').getAttribute('aria-selected')==='true')selectView('overview');
$('unitSummary').hidden=true;
$('unitBasis').hidden=true;for(const id of ['cards','income','expenses','accounts','transfers','obligations','paidFrom','warnings','otherMovements','incomeMatches','expensesMatches'])$(id).replaceChildren();
$('incomeSearchCount').textContent='';
$('expensesSearchCount').textContent='';
$('incomeMatchSection').hidden=true;
$('expensesMatchSection').hidden=true;
$('basis').textContent='';
$('comparison').textContent='';
$('note').textContent='';
$('status').textContent=error.message;}}
const reportBasis=text('p','');reportBasis.id='basis';reportBasis.className='muted';
